PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?oil * ?pct / 100) AS ?total) WHERE {
  { SELECT DISTINCT ?c WHERE { ?c a :Company ; :name ?n . FILTER(REGEX(?n, "^YPF( S\\.?A\\.?)?$", "i")) } }
  ?s a :Stake ; :partner ?c ; :concession ?con ; :percent ?pct .
  ?p a :WellProduction ; :concession ?con ; :oil ?oil .
}
